import {componentDefinitions,componentDefaults,validComponentProperties} from './scene-components.js';
export function sequenceComponent(object,track){const c=object?.components?.find(c=>c.id===track.component),field=c&&componentDefinitions[c.type]?.properties[track.property];if(!field||c.type!==track.componentType||!['number','checkbox','vec3','color','text','select','asset','sortinglayer'].includes(field.type))throw Error('시퀀스 컴포넌트 속성이 없어요: '+track.property);return {component:c,field,value:structuredClone(c.properties?.[track.property]??componentDefaults(c.type)[track.property])};}
export function validSequenceComponent(track,value){try{const type=track.componentType,field=componentDefinitions[type]?.properties[track.property];return typeof track.component==='string'&&track.component.length>0&&track.component.length<=100&&!!field&&['number','checkbox','vec3','color','text','select','asset','sortinglayer'].includes(field.type)&&validComponentProperties(type,{...componentDefaults(type),[track.property]:value});}catch{return false;}}
export function recordableComponents(object){const rows=[];for(const c of object.components||[]){if(c.type==='Transform')continue;for(const [property,field] of Object.entries(componentDefinitions[c.type]?.properties||{})){const row={component:c.id,componentType:c.type,property};const value=c.properties?.[property]??componentDefaults(c.type)[property];if(validSequenceComponent(row,value))rows.push({...row,value:structuredClone(value),discrete:!['vec3','color'].includes(field.type)&&(field.type!=='number'||field.step===1)});}}return rows;}
